Rewrite the following GNU C++11 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to rewrite:
<original_code>
#include<iostream>
#include<cstdlib>
#include<string>
#include<cstring>
#include<cstdio>
#include<algorithm>
#include<climits>
#include<cmath>
#include<cctype>
#include<stack>
#include<queue>
#include<list>
#include<vector>
#include<set>
#include<map>
#include<sstream>
using namespace std;

typedef long long LL;

const int inf=0x3f3f3f3f;

const int N=210;

struct Edge
{
	int to,w,next;
}edge[N*N];//边数

const int b[4][2]={0,1,0,-1,1,0,-1,0};

int n,t,st=N-1,ed=st-1,cap[15][15],sci[15][15],maze[65][15][15],head[N],cnt;

bool vis[15][15],dp[65][15][15][15][15];

void addedge(int u,int v,int w)
{
	edge[cnt].to=v;
	edge[cnt].w=w;
	edge[cnt].next=head[u];
	head[u]=cnt++;
	edge[cnt].to=u;
	edge[cnt].w=0;//反向边边权设置为0
	edge[cnt].next=head[v];
	head[v]=cnt++;
}

int d[N],now[N];//深度 当前弧优化

bool bfs(int s,int t)//寻找增广路
{
	memset(d,0,sizeof(d));
	queue<int>q;
	q.push(s);
	now[s]=head[s];
	d[s]=1;
	while(!q.empty())
	{
		int u=q.front();
		q.pop();
		for(int i=head[u];i!=-1;i=edge[i].next)
		{
			int v=edge[i].to;
			int w=edge[i].w;
			if(d[v])
				continue;
			if(!w)
				continue;
			d[v]=d[u]+1;
			now[v]=head[v];
			q.push(v);
			if(v==t)
				return true;
		}
	}
	return false;
}

int dinic(int x,int t,int flow)//更新答案
{
	if(x==t)
		return flow;
	int rest=flow,i;
	for(i=now[x];i!=-1&&rest;i=edge[i].next)
	{
		int v=edge[i].to;
		int w=edge[i].w;
		if(w&&d[v]==d[x]+1)
		{
			int k=dinic(v,t,min(rest,w));
			if(!k)
				d[v]=0;
			edge[i].w-=k;
			edge[i^1].w+=k;
			rest-=k;
		}
	}
	now[x]=i;
	return flow-rest;
}

int solve(int st,int ed)
{
	int ans=0,flow;
	while(bfs(st,ed))
		while(flow=dinic(st,ed,inf))
			ans+=flow;
	return ans;
}

int get_id(int x,int y,int k)//science:0 capsule:1
{
	return (x-1)*n+y+k*n*n;
}

void dfs(int x,int y,int xx,int yy,int step)
{
	vis[xx][yy]=true;
	dp[step][x][y][xx][yy]=true;
	if(step>=t||maze[step][xx][yy])
		return;
	for(int k=0;k<4;k++)
	{
		int nx=xx+b[k][0];
		int ny=yy+b[k][1];
		if(nx<=0||ny<=0||nx>n||ny>n)
			continue;
		if(vis[nx][ny])
			continue;
		if(maze[step][nx][ny])
			continue; 
		dfs(x,y,nx,ny,step+1);
	}
}

void init()
{
	memset(now,0,sizeof(now));
	memset(head,-1,sizeof(head));
	cnt=0;
	for(int time=1;time<=t;time++)
	{
		for(int x=1;x<=n;x++)
		{
			for(int y=1;y<=n;y++)
			{
				if(maze[time-1][x][y])
					maze[time][x][y]=maze[time-1][x][y];
				else
				{
					for(int k=0;k<4;k++)
					{
						int xx=x+b[k][0];
						int yy=y+b[k][1];
						if(xx<=0||yy<=0||xx>n||yy>n)
							continue;
						if(maze[time-1][xx][yy]==2)
							maze[time][x][y]=2;
					}
				}
			}
		}
	}
	for(int i=1;i<=n;i++)
	{
		for(int j=1;j<=n;j++)
		{
			if(sci[i][j])
			{
				memset(vis,false,sizeof(vis));
				dfs(i,j,i,j,0);
			}
		}
	}
	for(int i=1;i<=t;i++)
		for(int x=1;x<=n;x++)
			for(int y=1;y<=n;y++)
				for(int xx=1;xx<=n;xx++)
					for(int yy=1;yy<=n;yy++)
				dp[i][x][y][xx][yy]|=dp[i-1][x][y][xx][yy];
}

int main()
{
//  freopen("input.txt","r",stdin);
//  ios::sync_with_stdio(false);
	scanf("%d%d",&n,&t);
    for(int i=1;i<=n;i++)
    {
    	char s[15];
    	scanf("%s",s+1);
    	for(int j=1;j<=n;j++)
    	{
    		if(isdigit(s[j]))
    			sci[i][j]=s[j]-'0';
    		else if(s[j]=='Y')
    			maze[0][i][j]=1;
    		else if(s[j]=='Z')
    			maze[0][i][j]=2;
		}
	}
	for(int i=1;i<=n;i++)
	{
		char s[15];
		scanf("%s",s+1);
		for(int j=1;j<=n;j++)
		{
			if(isdigit(s[j]))
				cap[i][j]=s[j]-'0';
		}
	}
	init();
    for(int i=1;i<=n;i++)
    {
    	for(int j=1;j<=n;j++)
    	{
    		if(sci[i][j])
    			addedge(st,get_id(i,j,0),sci[i][j]);
    		if(cap[i][j])
    			addedge(get_id(i,j,1),ed,cap[i][j]);
		}
	}
	for(int x=1;x<=n;x++)
		for(int y=1;y<=n;y++)
			for(int xx=1;xx<=n;xx++)
				for(int yy=1;yy<=n;yy++)
					if(sci[x][y]&&cap[xx][yy]&&dp[t][x][y][xx][yy])
						addedge(get_id(x,y,0),get_id(xx,yy,1),inf);
	printf("%d\n",solve(st,ed));














    return 0;
}
    			   			 	  		 						 				//hellobig_tq
